set-variable.value:
@{
        var header = context.Request.Headers.GetValueOrDefault("Authorization","");
        if (string.IsNullOrEmpty(header)) { return ""; }
        var jwt = header.Replace("Bearer ","").AsJwt();
        return jwt == null ? "" : jwt.Claims.GetValueOrDefault("member_scope","");
    }

@{
        var q = context.Request.Url.Query;
        return q.GetValueOrDefault("identifier",
               q.GetValueOrDefault("patient",
               q.GetValueOrDefault("subject",
               q.GetValueOrDefault("beneficiary",""))));
    }

when.condition:
@{
          var scope = (string)context.Variables["memberScope"];
          if (string.IsNullOrEmpty(scope)) { return false; }
          var requested = (string)context.Variables["requestedMember"];
          return !requested.Contains(scope);
      }
